"""Module for Kafka producer"""
import logging
from time import sleep, monotonic
from typing import Any, Optional

from marvin_client.exceptions import TimeoutException
from kafka import KafkaProducer  # type: ignore
from marvin_client import utils

SEND_TIMEOUT = 60  # seconds
RESEND_DELAY = 5  # seconds

logger = logging.getLogger("marvin_client.kafka")


class KafkaClient:
    """Kafka producer class"""

    def __init__(self, bootstrap_servers: str) -> None:
        """
        Constructor.

        :param bootstrap_servers: Kafka bootstrap servers, e.g. "10.1.1.1:9092,10.1.1.2:9092"
        """
        assert bootstrap_servers

        self._bootstrap_servers = bootstrap_servers
        self._producer: Optional[KafkaProducer] = None

    def send(self, topic: str, message: Any, key: Optional[Any] = None, timeout: float = SEND_TIMEOUT) -> None:
        """
        Send message to Kafka topic.
        If sending fails, it is retried until timeout triggers.

        :param topic: Topic name
        :param message: Message to send. Message can be JSON string or any type convertible to JSON string.
        :param key: Kafka partition key
        :param timeout: Send timeout in seconds. Default 60 seconds.
        """
        logger.debug("Sending message to Kafka. Topic: %s, Message: %s", topic, message)

        assert topic
        assert message
        assert timeout > 0

        if not isinstance(message, str):  # message to JSON string
            message = utils.to_json(message)

        if not isinstance(key, bytes):  # key to bytes
            key = str(key).encode("utf-8")

        expiration_time = monotonic() + timeout

        while monotonic() < expiration_time:
            try:
                producer = self._get_producer()
                producer.send(topic, value=message.encode("utf-8"), key=key)
                producer.flush(timeout)
                logger.debug("Message sent to Kafka. Topic: %s", topic)
                return
            except Exception as ex:
                logger.debug("Sending message to Kafka failed. Retrying. Topic: %s. Error: %s", topic, exc_info=ex)
                self._close_producer()
                sleep(RESEND_DELAY)

        msg = f"Sending message to Kafka timed out. Timeout: {timeout} seconds"
        logger.debug(msg)

        raise TimeoutException(msg)

    def close(self) -> None:
        """Close Kafka client and underlying Kafka producer"""
        self._close_producer()

    def _get_producer(self) -> KafkaProducer:
        """
        Get singleton Kafka producer, i.e. it is created only if it does not exist yet.

        :return: Kafka producer
        """
        if self._producer is None:
            servers = [server.strip() for server in self._bootstrap_servers.split(",")]
            self._producer = KafkaProducer(bootstrap_servers=servers)
        return self._producer

    def _close_producer(self):
        """Close Kafka producer"""
        if self._producer is not None:
            self._producer.close(5)
            self._producer = None

    def __enter__(self) -> "KafkaClient":
        """
        Context manager entry.

        :return: This instance of Kafka client
        """
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        """Context manager exit. Closes the Kafka client."""
        self.close()
